INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (6, 'module_2_ee0c2bb1', 1, 'What is the pose of a rigid body?', '["Only the position of a reference point on the body.","Only the orientation of the body expressed by a rotation matrix.","The position and orientation of the body relative to a reference frame.","The set of all possible translations of the body."]', 'C', 'Pose = position (a translation vector) plus orientation (a rotation matrix); both are needed to fully describe a rigid body in space.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (7, 'module_2_ee0c2bb1', 2, 'Which of the following is true for any proper rotation matrix R âˆˆ SO(3)?', '["RTR = 0","RTR = I and det(R) = 1","R = RT always","det(R) = 0"]', 'B', 'Rotation matrices are orthogonal (RTR = I) and for proper (right-handed) rotations have determinant +1.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (8, 'module_2_ee0c2bb1', 3, 'Given pâ€² = [pâ€²x pâ€²y pâ€²z]^T in a frame rotated about z by Î±, the x-coordinate px in the original frame is', '["px = pâ€²x cosÎ± + pâ€²y sinÎ±","px = pâ€²x cosÎ± âˆ’ pâ€²y sinÎ±","px = pâ€²x","px = pâ€²z cosÎ± âˆ’ pâ€²y sinÎ±"]', 'B', 'Rz(Î±) acting on pâ€² yields px = pâ€²x cosÎ± âˆ’ pâ€²y sinÎ± (standard planar rotation formula).', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (9, 'module_2_ee0c2bb1', 4, 'The columns of a rotation matrix R represent:', '["The coordinates of the fixed-frame axes expressed in the current frame.","The coordinates of the current-frame axes expressed in the fixed frame.","Translation vectors between frames.","The eigenvectors of R with eigenvalue 0."]', 'B', 'Columns of R are the direction cosines of the rotated (current) axes expressed in the fixed frame.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (10, 'module_2_ee0c2bb1', 5, 'The inverse of a homogeneous transformation A = [R o; 0^T 1] is', '["A^T (transpose of A)","[R^T, âˆ’R^T o; 0^T, 1]","[R, âˆ’o; 0^T, 1]","[R^âˆ’1, o; 0^T, 1]"]', 'B', 'Inverse uses R^T for rotation and âˆ’R^T o for translation; A^T is not the inverse because A is not orthogonal as a 4Ã—4 matrix.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (11, 'module_2_ee0c2bb1', 6, 'Which statement about matrix products of finite rotations is correct?', '["Finite rotation matrices always commute: R1 R2 = R2 R1.","Finite rotations generally do not commute; order matters.","Finite rotations commute only when represented as quaternions.","Finite rotations commute if and only if det(R1) = det(R2)."]', 'B', 'In SO(3) matrix multiplication is generally non-commutative; the order of finite rotations affects the result.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (12, 'module_2_ee0c2bb1', 7, 'SE(3) denotes:', '["The set of 3Ã—3 symmetric matrices.","The set of all 3D translations only.","The group of rigid-body motions combining R^3 translations and SO(3) rotations.","The special orthogonal group of 3Ã—3 rotations."]', 'C', 'SE(3) = R^3 Ã— SO(3), the group of 3D rigid body poses (rotation + translation).', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (13, 'module_2_ee0c2bb1', 8, 'For infinitesimal rotations by small angles dÏ†x, dÏ†y, dÏ†z, which is true to first order?', '["They remain non-commutative at first order.","They commute to first order: combining two infinitesimal rotations is additive.","Their matrices are singular.","They produce a scaling effect."]', 'B', 'To first order (linear approximation) small-angle rotation matrices commute and combine by angle addition.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (14, 'module_2_ee0c2bb1', 9, 'If you perform two successive rotations about the current axes: first R1, then R2, the overall rotation matrix is:', '["R = R2 R1 (premultiplication)","R = R1 + R2","R = R1 R2 (postmultiplication)","R = R1^T R2"]', 'C', 'When rotations are specified about the current (moving) axes, you postmultiply in execution order: R = R1 R2.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (15, 'module_2_ee0c2bb1', 10, 'In ZYZ Euler angles (Ï•, Ï‘, Ïˆ) using the current-frame convention, what happens when sinÏ‘ = 0?', '["All three angles are uniquely determined.","The first and last rotations are about parallel axes and only their sum or difference is determined (a singularity).","The representation becomes a quaternion automatically.","Ï‘ must be set to Ï€/2."]', 'B', 'sÏ‘ = 0 (Ï‘ = 0 or Ï€) causes axis alignment (gimbal lock) so Ï• and Ïˆ become coupled; only combination is determinable.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (16, 'module_2_ee0c2bb1', 11, 'For ZYX (RPY) Euler angles with Ï‘ âˆˆ (âˆ’Ï€/2, Ï€/2), Ï† (roll about z) can be extracted from R by:', '["Ï† = Atan2(r31, r11)","Ï† = Atan2(r21, r11)","Ï† = Atan2(r12, r21)","Ï† = Atan2(r11, r21)"]', 'B', 'Standard inverse mapping gives Ï• = Atan2(r21, r11) for the ZYX (premultiplication) convention.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (17, 'module_2_ee0c2bb1', 12, 'Given a rotation matrix R, the rotation angle Ï‘ in the angleâ€“axis representation is computed as:', '["Ï‘ = sinâˆ’1((r11 + r22 + r33 âˆ’ 1)/2)","Ï‘ = tanâˆ’1((r21 âˆ’ r12)/something)","Ï‘ = cosâˆ’1((r11 + r22 + r33 âˆ’ 1)/2)","Ï‘ = Atan2(r11, r22)"]', 'C', 'Angle is given by Ï‘ = arccos((trace(R) âˆ’ 1)/2).', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (18, 'module_2_ee0c2bb1', 13, 'A unit quaternion Q = {Î·, Îµ} relates to angleâ€“axis (Ï‘, r) by:', '["Î· = sin(Ï‘), Îµ = cos(Ï‘) r","Î· = cos(Ï‘/2), Îµ = sin(Ï‘/2) r","Î· = Ï‘, Îµ = r","Î· = cosÏ‘, Îµ = sinÏ‘ r"]', 'B', 'Quaternion scalar part Î· = cos(Ï‘/2), vector part Îµ = sin(Ï‘/2) r; ensures unit norm.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (19, 'module_2_ee0c2bb1', 14, 'For a time-varying rotation R(t), what property does á¹˜(t) RT(t) have and why is it important?', '["It is symmetric and equals the identity.","It is skew-symmetric; this relates RÌ‡ to angular velocity.","It is diagonal and gives principal rotations.","It is zero for all t."]', 'B', 'Differentiating RTR = I gives á¹˜ RT + (á¹˜ RT)^T = 0, so á¹˜ RT is skew-symmetric; this leads to the angular velocity matrix S(Ï‰).', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (20, 'module_2_ee0c2bb1', 15, 'In the Denavitâ€“Hartenberg (DH) convention, the homogeneous transform for a revolute joint i (parameters ai, Î±i, di, Î¸i) depends functionally on which variable?', '["ai only","Î±i only","Î¸i (joint variable) for revolute joint; di for prismatic","di for revolute joints"]', 'C', 'For a revolute joint the joint variable is Î¸i; di is fixed. For prismatic, di is variable.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (21, 'module_2_ee0c2bb1', 16, 'If Q1 and Q2 are unit quaternions representing rotations R1 and R2, the quaternion representing R1 followed by R2 (R = R1 R2) is given by:', '["Q1 + Q2","Q1 * Q2 using quaternion multiplication: {Î·1Î·2 âˆ’ Îµ1^TÎµ2, Î·1Îµ2 + Î·2Îµ1 + Îµ1 Ã— Îµ2}","Component-wise product of Î· and Îµ","Q2 * Q1 (reverse order always)"]', 'B', 'Quaternion composition corresponds to the given noncommutative multiplication; order matters matching rotation order.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (22, 'module_2_ee0c2bb1', 17, 'For angleâ€“axis recovery when Ï‘ = Ï€ (180Â°), how can the unit axis r be recovered from R?', '["r = (1/(2 sinÏ‘)) [r32 âˆ’ r23, ...] (works since sinÏ‘ â‰  0)","Use r_i^2 = (rii + 1)/2 and r_i r_j = rij/2 to solve for components (special Ï€-case)","Axis is arbitrary; any vector works","Use Atan2 on off-diagonal elements only"]', 'B', 'At Ï‘ = Ï€, sinÏ‘ = 0 so the standard formula fails; instead R = 2 r r^T âˆ’ I gives r_i^2 = (rii+1)/2 and r_i r_j = rij/2 to recover r (up to sign).', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (23, 'module_2_ee0c2bb1', 18, 'When extracting a quaternion from R using Î· = (1/2) sqrt(r11 + r22 + r33 + 1), why is it common to enforce Î· â‰¥ 0?', '["To ensure the quaternion has unit length.","To select a unique representative since Q and âˆ’Q represent the same rotation.","Because Î· must always be positive for physical rotations.","To avoid computing square roots."]', 'B', 'Quaternions Q and âˆ’Q map to the same rotation; choosing Î· â‰¥ 0 picks a consistent representative and avoids arbitrary sign flips.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (24, 'module_2_ee0c2bb1', 19, 'In inverse kinematics using orientation error defined by R_err = Rd Re^T and angleâ€“axis (Ï‘, r) with eO = r sinÏ‘, why is the mapping eO unique for âˆ’Ï€/2 < Ï‘ < Ï€/2 and useful for control?', '["Because sinÏ‘ is always zero there.","Because eO avoids representation singularities and is small for small errors, enabling linearization with the geometric Jacobian.","Because r is undefined in this range.","Because quaternions cannot represent errors in this interval."]', 'B', 'For small errors (|Ï‘| < Ï€/2) r sinÏ‘ uniquely represents orientation error and behaves linearly, making it suitable with the geometric Jacobian for control law design.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (25, 'module_2_ee0c2bb1', 20, 'A manipulator Jacobian J is mÃ—n with n > m (redundant robot). Which statement about computing a joint velocity qÌ‡ to achieve a task velocity xÌ‡ is correct in practice near singularities?', '["Use the exact inverse Jâˆ’1 (always exists).","Use the left pseudo-inverse J^+ = J^T (J J^T)^âˆ’1 to get the minimum-norm solution; near singularities, apply damping (damped least squares) for robustness.","Use the right pseudo-inverse (J^T J)^âˆ’1 J^T even when n > m.","Any solution is equally good; singularities don''t matter."]', 'B', 'For n > m, the left pseudo-inverse gives the minimum-norm qÌ‡; near singularities (J J^T ill-conditioned) damped least-squares regularization stabilizes the solution.', NULL, '2025-12-14T23:16:18.139Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (26, 'module_1_e88e9f45', 1, 'Which statement best captures the technical definition of a robot given in the module?', '["A machine that can only perform one repetitive industrial task with no reprogramming.","A reprogrammable, multifunctional manipulator that moves materials, parts, tools, or devices through programmed motions.","Any autonomous vehicle that navigates outdoors without human intervention.","A purely software agent that reasons about physical tasks but does not act in the physical world."]', 'B', 'The module defines an industrial-type robot as a reprogrammable, multifunctional manipulator for moving materials/tools via programmed motions.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (27, 'module_1_e88e9f45', 2, 'Given unit vectors n_e, s_e, a_e and position p_e of an end-effector in a base frame, which homogeneous transformation expresses the direct kinematics map T^b_e(q)?', '["[ n_e s_e a_e; p_e 0 0 1 ]","[ n_e s_e a_e p_e; 0 0 0 1 ]","[ p_e n_e s_e a_e; 1 0 0 0 ]","[ n_e^T; s_e^T; a_e^T; p_e^T ]"]', 'B', 'The homogeneous transform stacks the 3x3 rotation [n_e s_e a_e] and the 3x1 position p_e with a bottom row [0 0 0 1].', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (28, 'module_1_e88e9f45', 3, 'Which manipulator geometry naturally yields straight-line Cartesian motions and uniform positioning accuracy in a rectangular workspace?', '["Anthropomorphic (RRR)","Cylindrical (RPP)","Cartesian (PPP)","Spherical (RRP)"]', 'C', 'Cartesian robots use three orthogonal prismatic joints, giving direct mapping to Cartesian coordinates and straight-line motions.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (29, 'module_1_e88e9f45', 4, 'In the Denavitâ€“Hartenberg framework, which problem is primarily addressed?', '["Sensor calibration for cameras","Building the direct kinematics of serial manipulators","Designing PID gains for servo loops","Generating potential fields for obstacle avoidance"]', 'B', 'The DH convention provides a systematic method to assign frames and derive direct kinematics for serial chains.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (30, 'module_1_e88e9f45', 5, 'Which of the following is a proprioceptive sensor example and why is it important?', '["Camera â€” because it measures environment features","Force-torque sensor on the wrist â€” because it estimates contact forces","Joint encoder â€” because it measures internal joint angles for feedback control","Lidar â€” because it maps the external scene"]', 'C', 'Proprioceptive sensors measure the robot''s internal state (e.g., joint encoders for joint angles), essential for servo-level control.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (31, 'module_1_e88e9f45', 6, 'Which mobile base type is characterized by two driven wheels on a common axle and often a caster for support?', '["Tricycle","Differential-drive","Synchro-drive","Car-like"]', 'B', 'Differential-drive uses two independently driven wheels on a common axle and typically a caster for balance.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (32, 'module_1_e88e9f45', 7, 'Which programming paradigm is described as recording joint positions via a teach pendant for later playback?', '["Object-oriented programming","Robot-oriented programming","Teaching-by-showing","Functional programming"]', 'C', 'Teaching-by-showing records operator-demonstrated joint positions with a pendant for playback.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (33, 'module_1_e88e9f45', 8, 'For achieving arbitrary 3D orientation at the wrist independent of the arm, what minimum wrist DOFs are required?', '["1 revolute joint","2 prismatic joints","3 revolute joints (spherical wrist)","4 mixed joints"]', 'C', 'Three revolute joints in a spherical wrist provide full 3D orientation decoupled from positioning.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (34, 'module_1_e88e9f45', 9, 'Practical application: You need high stiffness and payload capacity for heavy, high-speed pick-and-place in a factory. Which structural choice is most appropriate?', '["Serial anthropomorphic arm (fully revolute)","Parallel mechanism or closed-chain architecture","Lightweight, redundant seven-axis arm","SCARA with long horizontal reach"]', 'B', 'Parallel/closed-chain structures give high stiffness and payload capacity and are suitable for heavy/high-speed precision tasks.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (35, 'module_1_e88e9f45', 10, 'Which motion-planning method is probabilistic and samples the robotâ€™s configuration space to build a connectivity graph?', '["Cell decomposition","Probabilistic Roadmap (PRM)","Artificial potential fields","Retraction method"]', 'B', 'PRMs sample configurations probabilistically and connect them into a roadmap for planning.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (36, 'module_1_e88e9f45', 11, 'Medium difficulty â€” In orientation error measure e_O = 1/2 (n_e Ã— n_d + s_e Ã— s_d + a_e Ã— a_d), which additional consistency conditions must be checked before using e_O as a corrective term?', '["n_e^T n_d â‰¤ 0, s_e^T s_d â‰¤ 0, a_e^T a_d â‰¤ 0","n_e^T n_d â‰¥ 0, s_e^T s_d â‰¥ 0, a_e^T a_d â‰¥ 0","n_e Ã— n_d = 0, s_e Ã— s_d = 0, a_e Ã— a_d = 0","No consistency checks are required"]', 'B', 'The module specifies these dot-product conditions to ensure consistent, non-ambiguous orientation alignment before using e_O.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (37, 'module_1_e88e9f45', 12, 'Medium difficulty â€” Which statement best explains the difference between kinematics and differential kinematics?', '["Kinematics deals with dynamics; differential kinematics deals with statics.","Kinematics maps joint-space to pose; differential kinematics relates joint velocities to end-effector velocities (via the Jacobian).","Kinematics is only for mobile robots; differential kinematics is for manipulators.","There is no difference â€” they are synonyms."]', 'B', 'Kinematics gives pose mappings; differential kinematics studies velocities and small motions using Jacobians.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (38, 'module_1_e88e9f45', 13, 'Practical application / Medium â€” You must design a vision-guided grasp: which sequence best follows the courseâ€™s integrative thread?', '["Execute grasp; then estimate object pose; then plan trajectory.","Calibrate camera; determine object pose; generate orientation trajectory; compute direct kinematics; execute with control law using orientation error.","Use only teach pendant motions without sensing; rely on repeatability.","Plan a path with PRM ignoring vision; hope the object is at the expected place."]', 'B', 'The integrative thread emphasizes perception (calibration, pose), planning orientation trajectory, deriving kinematics, and control based on orientation error before execution.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (39, 'module_1_e88e9f45', 14, 'Hard â€” Which of the following correctly distinguishes integrable vs. non-integrable kinematic constraints for mobile robots?', '["Integrable constraints permit instantaneous motion only; non-integrable allow arbitrary reconfiguration over time.","Integrable constraints reduce the configuration space dimension; non-integrable constraints do not.","Integrable (holonomic) constraints restrict configuration coordinates directly and are path-independent; non-integrable (nonholonomic) constraints restrict velocities and are path-dependent, so some poses are reachable only via specific maneuvers.","There is no difference; both types impose identical reachability properties."]', 'C', 'Holonomic (integrable) constraints constrain configuration coordinates; nonholonomic (non-integrable) constrain velocities and require specific maneuvers to reach certain poses.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (40, 'module_1_e88e9f45', 15, 'Hard â€” In designing a safety-critical robot control system, which level of the hierarchical functional model is primarily responsible for high-speed real-time servo commands and immediate fail-safe responses?', '["Task level","Action level","Primitive level","Servo level"]', 'D', 'The servo level handles real-time motor commands, proprioception, and immediate safety responses like interrupts and bounded actuation.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (41, 'module_1_e88e9f45', 16, 'Easy â€” Which sensing modality is most crucial for regulating contact force during polishing or assembly?', '["Lidar ranging","Joint encoders only","Force/torque sensing (exteroceptive)","Infrared temperature sensing"]', 'C', 'Force/torque sensors provide the necessary contact force information for safe force-regulated interaction tasks.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (42, 'module_1_e88e9f45', 17, 'Medium â€” Compare industrial and advanced robotics: which statement is true about autonomy and environment structure?', '["Industrial robotics requires high autonomy and operates in unstructured environments.","Advanced robotics operates in highly structured, known environments with limited autonomy.","Industrial robotics typically works in structured environments with limited autonomy; advanced robotics requires high autonomy in scarcely structured or unstructured environments.","There is no difference in autonomy or environment structure between the two."]', 'C', 'Industrial systems rely on known, structured settings with limited autonomy; advanced robots handle uncertain, unstructured environments and need greater autonomy.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (43, 'module_1_e88e9f45', 18, 'Hard â€” When using laser-based 3D sensing in a factory, which two safety/robustness issues should be explicitly addressed according to the module?', '["Battery life and wireless bandwidth","Eye-safety (especially invisible IR) and false specular reflections from polished surfaces","Only ambient temperature effects","Encoder drift and motor backlash"]', 'B', 'The module highlights laser eye-safety concerns and reliability problems due to specular reflections; these must be mitigated in design.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (44, 'module_1_e88e9f45', 19, 'Easy â€” Which manipulation structure is especially suited for vertical assembly tasks due to compliance in the horizontal plane and stiffness vertically?', '["Spherical (RRP)","SCARA (Selective Compliance Assembly Robot Arm)","Cartesian (PPP)","Parallelogram closed-chain"]', 'B', 'SCARA arms are designed with selective compliance (horizontal) beneficial for vertical assembly tasks.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (45, 'module_1_e88e9f45', 20, 'Medium â€” Which programming environment feature most directly supports safe concurrent task execution and interrupt-driven recovery in industrial robots?', '["Batch file execution without interrupts","Real-time operating system with interrupt handling, PLC-like functions, and concurrency control","Ad-hoc scripts with no synchronization primitives","Only a teach pendant with manual replay"]', 'B', 'Real-time OS features (interrupts, PLC-like determinism, concurrency control) enable predictable, safe handling of concurrent tasks and recovery.', NULL, '2025-12-14T23:29:15.810Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (46, 'course_17dbc904', 1, 'Which statement best defines a closed-loop control system in speech?', '["Speech is produced solely from preplanned motor commands with no feedback.","Speech production uses sensors that provide feedback to the controller, enabling real-time correction.","Speech production is driven only by memory without any sensory monitoring.","Speech depends only on breath regulation and not on sensory input."]', 'B', 'Closed-loop control means sensors (auditory and proprioceptive) return information to the mind/controller so speech can be corrected and coordinated in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (47, 'course_17dbc904', 2, 'In the closed-loop model of speech, which element is the "plant" or output?', '["The mind that generates motor commands","The ears that receive acoustic signals","The mouth and articulators that produce speech","Long-term memory stores of words"]', 'C', 'The plant/output is the articulatory system (mouth) that physically generates the spoken signal.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (48, 'course_17dbc904', 3, 'What distinguishes an open-loop control system (conceptual contrast) from a closed-loop system in speech?', '["Open-loop systems use auditory feedback but ignore proprioception.","Open-loop systems lack sensor-derived feedback to the controller during ongoing production.","Open-loop systems rely exclusively on proprioceptive feedback.","Open-loop systems constantly correct speech using sensory input."]', 'B', 'By contrast, open-loop systems would not receive sensory feedback during production and therefore would not make online corrections.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (49, 'course_17dbc904', 4, 'Which of the following is a primary function of proprioceptive feedback in speech?', '["To provide long-term storage of vocabulary","To supply real-time information about muscle positions and movements for pronunciation control","To amplify the acoustic signal so listeners can hear better","To store syntactic rules in memory"]', 'B', 'Proprioception supplies immediate information about articulatory states, enabling fine-tuning of pronunciation in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (50, 'course_17dbc904', 5, 'Auditoryâ€“proprioceptive integration in speech control primarily enables:', '["The replacement of breath regulation with memory recall","Constant calibration of motor output by combining what is heard with what is felt","Turning off sensory inputs during fluent speech","Storage of phonemes in long-term memory"]', 'B', 'Integration of auditory and proprioceptive feedback allows continual adjustment (calibration) to align produced sounds with intended targets.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (51, 'course_17dbc904', 6, 'How does breath regulation fit into the closed-loop architecture of speech control?', '["Breath is independent and not coordinated with sensory feedback.","Breath is regulated prior to speech and remains static during production.","Breath timing and pressure are coordinated with auditory and proprioceptive feedback to sustain fluent output.","Breath only affects loudness and has no role in real-time control."]', 'C', 'Breath regulation is coordinated with sensory streams (auditory/proprioceptive) to maintain timing, pressure, and fluency during speech.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (52, 'course_17dbc904', 7, 'Which sequence best represents the closed-loop walk-through example of speech production?', '["Production â†’ Memory â†’ Correction â†’ Feedback","Intended speech (mind) â†’ Production (mouth) â†’ Feedback (ears/nerve sensors) â†’ Correction (mind)","Feedback â†’ Production â†’ Memory â†’ Controller","Controller â†’ No feedback â†’ Production â†’ Correction after speech"]', 'B', 'The mind formulates intent, the mouth produces it, sensors provide feedback, and the mind corrects in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (53, 'course_17dbc904', 8, 'Practically, what is a likely immediate effect if proprioceptive feedback from the mouth is temporarily reduced?', '["Improved ability to choose syntactic structures","Difficulty fine-tuning pronunciation and less precise articulatory adjustments","Complete inability to breathe during speech","Faster speech planning with fewer errors"]', 'B', 'Reduced proprioception impairs real-time regulation of muscle positions, leading to less precise pronunciation and fewer immediate corrections.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (54, 'course_17dbc904', 9, 'The course states proprioception provides partial control over syntax. Which example illustrates that idea?', '["Remembering a verbâ€™s meaning after the conversation","Changing muscle sequences to produce â€œrunâ€ versus â€œranâ€ when switching tense","Hearing someone else speak and imitating their accent","Using breath alone to express emotion without words"]', 'B', 'Producing different word forms (tense/person) requires distinct muscular sequences guided by proprioceptive feedback as the utterance is executed.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (55, 'course_17dbc904', 10, 'Which sensory sources are explicitly identified as providing feedback in the closed-loop speech system?', '["Visual feedback from lip reading only","Auditory feedback from the ears and nerve sensors/proprioception in the mouth","Taste and olfactory cues","Vestibular sense from inner ear exclusively"]', 'B', 'The text specifies auditory feedback (ears) and nerve sensors/proprioceptive feedback in the mouth as primary sensory inputs.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (56, 'course_17dbc904', 11, 'If a speaker relies mainly on preplanned motor commands (open-loop-like behavior) during a rapid, rehearsed sentence, what practical risk increases?', '["Greater ability to correct deviations online","Reduced need for memory","Increased persistence of errors because sensory feedback isnâ€™t used for real-time correction","Immediate improvement in pronunciation accuracy"]', 'C', 'Without using sensory feedback for online adjustments, deviations from intent are less likely to be corrected while speaking, so errors can persist.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (57, 'course_17dbc904', 12, 'How does memory contribute to closed-loop control of speech?', '["Memory replaces the need for sensory feedback entirely.","Memory stores intended speech goals and supports preplanned motor commands that are refined by incoming feedback.","Memory only controls breath regulation and nothing else.","Memory provides proprioceptive signals directly to the mouth."]', 'B', 'Memory holds targets and linguistic intent; these form the goals that controllers aim for and refine through sensory feedback during production.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (58, 'course_17dbc904', 13, 'Practical application: Which step-by-step approach best uses auditory and proprioceptive feedback to improve a mispronounced consonant?', '["Ignore feedback, speak faster, and memorize a written rule","Listen to a model, slowly articulate target while attending to tongue position (proprioception), compare auditory result, and iteratively adjust","Only practice breathing exercises without articulatory focus","Rely solely on watching someone elseâ€™s lips without producing the sound yourself"]', 'B', 'Effective practice combines auditory modeling with active attention to proprioceptive sensations and iterative adjustmentsâ€”consistent with closed-loop integration.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (59, 'course_17dbc904', 14, 'What is a likely effect on closed-loop speech control if auditory feedback is delayed (e.g., delayed auditory feedback devices)?', '["Speakers immediately produce perfect speech with no corrections","The timing and coordination of speech can be disrupted, making real-time corrections harder","Proprioceptive feedback completely compensates with no change in performance","Breath regulation becomes unnecessary"]', 'B', 'Delayed auditory feedback interferes with the real-time calibration process, often disrupting timing and coordination and making corrections less effective.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (60, 'course_17dbc904', 15, 'Which scenario best demonstrates coordination among auditory feedback, proprioception, and breath regulation?', '["Whispering a sentence without regard to air pressure or muscle placement","Producing a sustained vowel with controlled breath pressure while monitoring tongue tension and the sound heard to maintain pitch and clarity","Reading silently without vocalizing","Tapping a rhythm with fingers while reciting a poem mentally"]', 'B', 'Sustaining a vowel requires breath support, proprioceptive monitoring of articulators, and auditory feedback to calibrate pitch and clarityâ€”illustrating integrated control.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (61, 'course_17dbc904', 16, 'In terms of information flow, which arrow correctly describes the closed-loop feedback process?', '["Plant â†’ Controller â†’ Sensors â†’ Output","Controller â†’ Plant (mouth) â†’ Sensors (ears/nerve) â†’ Controller","Sensors â†’ Plant â†’ Controller â†’ Memory only","Controller â†’ Sensors â†’ Plant â†’ No return loop"]', 'B', 'The controller issues motor commands to the plant; the resulting output is sensed and fed back to the controller for correctionâ€”forming a loop.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (62, 'course_17dbc904', 17, '(Hard, synthesis) Predict the combined impact on spoken syntax and pronunciation if both auditory feedback and proprioceptive feedback were significantly impaired simultaneously.', '["Minor changes limited only to loudness","Severe reductions in the ability to calibrate pronunciation and realize syntactic choices accurately during speech, with increased errors and less fluency","Improved grammatical accuracy but worse pronunciation","No effect because memory alone suffices"]', 'B', 'Both feedback streams are essential for real-time calibration of articulatory sequences that realize pronunciation and partial syntax control; impairing both disrupts execution, increasing errors and reducing fluency.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (63, 'course_17dbc904', 18, '(Hard, application/synthesis) For a therapy aimed at helping a learner produce past-tense endings (-ed), which combined strategy best leverages closed-loop and proprioceptive principles?', '["Teach the rule abstractly without speaking practice","Have the learner produce target verbs aloud, focus on the tongue/voicing sensations for -d/-t/-Éªd endings, use immediate auditory replay, and iteratively adjust with breath support","Only correct written exercises","Delay feedback so the learner cannot hear their own production"]', 'B', 'This strategy integrates proprioceptive attention (muscle/voicing sensations), immediate auditory feedback (closed-loop), and breath support to iteratively refine the motor sequences for tense realization.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (64, 'course_17dbc904', 19, '(Hard, theoretical) Why is a closed-loop architecture advantageous for speech production given limitations of memory and neurological processing?', '["It eliminates the need for any motor planning","It allows continuous, sensor-driven corrections that compensate for variability and reduce reliance on perfect preplanning stored in memory","It makes speech entirely reflexive and not linguistic","It stores all possible utterances in long-term memory to avoid online control"]', 'B', 'Closed-loop control enables the system to correct ongoing deviations, compensating for imperfect planning and neural noise, thus reducing the need for perfect preplanned motor sequences.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (65, 'course_17dbc904', 20, '(Hard, experimental synthesis) Which experimental manipulation most directly tests the relative contribution of auditory versus proprioceptive feedback in online speech correction?', '["Asking participants to read silently and report feelings","Applying a transient alteration to auditory feedback (e.g., pitch shift) while concurrently using a local anesthetic to reduce oral proprioception, then measuring corrective responses","Measuring vocabulary size with a written test","Observing speakers in complete silence with no measurement"]', 'B', 'Altering auditory feedback and reducing proprioception simultaneously allows researchers to observe how each feedback stream contributes to online corrections by examining changes in corrective behavior.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (66, 'course_17dbc904', 21, 'Which of the following best describes why speech is characterized as a closed-loop system?', '["Speech relies solely on preplanned motor commands without sensory input.","Sensory feedback from the ears and mouth is used to correct and coordinate ongoing speech in real time.","The mouth produces speech independently of any control from the mind.","Feedback is only used after a sentence is completed to adjust future utterances."]', 'B', 'Closed-loop means ongoing sensory feedback (auditory and proprioceptive) is routed to the controller (mind) to correct and coordinate speech in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (67, 'course_17dbc904', 22, 'In the closed-loop model of speech, what is the â€œplantâ€?', '["The mind that issues motor commands","The ears that provide auditory feedback","The mouth that produces the spoken signal","The memory systems that store targets"]', 'C', 'In control terminology, the plant/output is the body part producing the outputâ€”here, the mouth producing speech.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (68, 'course_17dbc904', 23, 'Which sensors are explicitly mentioned as providing feedback in the course content?', '["Visual and vestibular sensors","Auditory and nerve (proprioceptive) sensors in the mouth","Tactile sensors on the skin only","Olfactory receptors and taste buds"]', 'B', 'The content emphasizes auditory feedback from the ears and proprioceptive/nerve sensors in the mouth.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (69, 'course_17dbc904', 24, 'If speech were purely open-loop (conceptual contrast), which of the following consequences would be expected?', '["Real-time correction of errors based on what is heard","Speech would be continuously adjusted by proprioceptive feedback","Deviations from intended output would not be corrected during speaking","Breath regulation would automatically correct syntactic errors"]', 'C', 'An open-loop system lacks sensor-derived feedback during production, so online corrections would not occur.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (70, 'course_17dbc904', 25, 'Proprioceptive feedback primarily provides the mind with information about:', '["Acoustic properties of speech heard by others","Positions and movements of the speech musculature in real time","Grammatical rules stored in long-term memory","Visual cues from a conversation partner"]', 'B', 'Proprioception conveys information about body/muscle positions and movements, crucial for articulatory control.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (71, 'course_17dbc904', 26, 'How does proprioceptive feedback contribute to pronunciation during speech?', '["It stores vocabulary items for later use","It supplies the mind with immediate information about muscle state so adjustments can be made while speaking","It replaces auditory feedback entirely","It only operates after speech is finished"]', 'B', 'Proprioception gives immediate muscular-state information enabling fine-tuning of articulation in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (72, 'course_17dbc904', 27, 'Which statement best captures the relationship between auditory and proprioceptive feedback?', '["They are independent and never influence each other","Auditory feedback is used only for syntax, proprioception only for breath control","The mind integrates both streams to continually calibrate muscular actions and acoustic outcomes","Proprioceptive feedback is slower and therefore less useful than auditory feedback"]', 'C', 'The course describes auditoryâ€“proprioceptive integration where both are combined for constant calibration of speech.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (73, 'course_17dbc904', 28, 'Which component supports the formation and maintenance of intended speech goals within the closed-loop system?', '["The plant (mouth) only","Memory and neurological functions","External listeners","Visual feedback mechanisms"]', 'B', 'Memory and neurological functions help form and maintain intended targets that guide motor commands.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (74, 'course_17dbc904', 29, 'Practical application: A learner speaks and hears their output slightly delayed through headphones. Which aspect of the closed-loop system is being interfered with, and what is a likely immediate effect?', '["Breath regulation; increased lung capacity","Proprioceptive feedback; inability to move articulators","Auditory feedback timing; disruptions to fluency and real-time correction","Memory encoding; loss of vocabulary"]', 'C', 'Delayed auditory feedback alters the timing of auditory feedback, often disrupting fluency and online correction processes.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (75, 'course_17dbc904', 30, 'According to the course content, proprioceptive feedback contributes to partial control over syntax by:', '["Rewriting grammatical rules in long-term memory","Guiding the muscular sequences that realize different word forms (e.g., tense/person) in real time","Ensuring that breath supply dictates word order","Allowing visual cues to determine syntactic choices"]', 'B', 'Proprioception helps execute the precise muscle sequences needed to produce different word forms, influencing syntactic realization during speech.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (76, 'course_17dbc904', 31, 'Which of the following is an example of the closed-loop correction process described in the walkthrough example?', '["Planning an entire paragraph in advance and reciting it without change","The mind comparing what is heard from the ears to the intended target and adjusting articulation mid-utterance","Only using memory to choose words after the conversation ends","Relying on written notes instead of sensory feedback"]', 'B', 'The walkthrough shows the mind using auditory feedback to compare ongoing output to intended targets and make real-time adjustments.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (77, 'course_17dbc904', 32, 'Medium-hard synthesis: How do breath regulation and proprioceptive feedback jointly support fluent long utterances?', '["Breath regulation replaces proprioception so muscles don''t need feedback","Proprioceptive feedback times breath release directly without mind involvement","Breath timing and pressure are coordinated with proprioceptive signals to align muscular activity and sustain fluent output","They function in separate loops and thus do not interact"]', 'C', 'The content states breath regulation is coordinated with proprioceptive and auditory streams so muscular activity aligns with breath support for fluency.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (78, 'course_17dbc904', 33, 'Which of the following best represents a theoretical implication if proprioceptive feedback were entirely absent?', '["Speech would still be perfectly accurate due to auditory feedback alone","Pronunciation and the moment-to-moment realization of syntax would be severely impaired because real-time muscular information would be lacking","Memory formation would instantly cease","The mouth would produce sounds but without any neural control"]', 'B', 'The course emphasizes proprioception as indispensable for regulating pronunciation and contributing to syntax; absence would impair these functions.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (79, 'course_17dbc904', 34, 'Application question (medium): For a learner trying to improve articulation of a difficult consonant, which practice leverages proprioceptive feedback most directly?', '["Repeating the consonant silently without moving articulators","Practicing the consonant aloud while attending to the feeling of tongue and lip positions and making small real-time adjustments","Only listening to recordings of the consonant performed by native speakers","Memorizing a grammar rule about consonant clusters"]', 'B', 'Attending to and adjusting articulator positions uses proprioceptive feedback to fine-tune pronunciation in real time.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (80, 'course_17dbc904', 35, 'Hard: How does the role of memory differ between open-loop and closed-loop conceptualizations of speech control, according to the course content?', '["Memory is irrelevant in both models","In open-loop, memory supplies preplanned commands for execution without correction; in closed-loop, memory supplies targets that are maintained while sensory feedback enables online adjustments","In closed-loop, memory prevents any use of sensory feedback","Memory only stores acoustic templates and does not influence motor commands"]', 'B', 'The course contrasts open-loop reliance on preplanned commands from memory without online correction versus closed-loop where memory supplies targets but sensory feedback allows real-time adjustments.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (81, 'course_17dbc904', 36, 'Medium synthesis: A speaker unintentionally uses the wrong verb tense mid-sentence but corrects it before finishing. Which mechanisms most likely enabled that immediate correction?', '["Visual feedback and long-term memory retrieval","Preplanned open-loop motor program without sensory influence","Integration of auditory feedback and proprioceptive feedback routed to the controller, allowing comparison to intended target and quick adjustment","External listener interruption and correction"]', 'C', 'Immediate mid-sentence corrections are enabled by closed-loop integration of auditory and proprioceptive feedback informing the controller to adjust motor actions.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (82, 'course_17dbc904', 37, 'Easy practical: Which practice would directly strengthen auditoryâ€“proprioceptive integration for a language learner?', '["Reading silently while walking","Shadowing (speaking along with a recording) while focusing on both sounds heard and articulator sensations","Memorizing irregular verb lists without speaking","Only watching videos with subtitles"]', 'B', 'Shadowing while attending to sound and articulator sensations exercises integration of auditory and proprioceptive feedback.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (83, 'course_17dbc904', 38, 'Hard: Consider a clinical scenario where a patient has reduced proprioceptive sensation in the oral muscles but intact hearing. Based on the course content, which pattern is most likely?', '["No speech effects because auditory feedback fully compensates","Pronunciation clarity and fine-grained syntactic realizations may degrade because proprioception uniquely contributes to moment-to-moment muscular regulation","Breath regulation will entirely fail leading to immediate inability to speak","Memory will automatically re-route to visual feedback to restore normal speech"]', 'B', 'The course states proprioception is indispensable for fine articulation and partial syntax control; intact hearing may help but cannot fully compensate.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (84, 'course_17dbc904', 39, 'Medium: Which phrase best summarizes the â€œconstant calibrationâ€ idea in speech control?', '["The mind calibrates its taste preferences based on speech sounds","The mind continually adjusts muscular actions by combining auditory and proprioceptive feedback so produced sounds match intended targets","Calibration occurs only during language learning, not during fluent speech","Calibration refers to adjusting microphone settings during recording"]', 'B', 'Constant calibration refers to ongoing integration of auditory and proprioceptive feedback to align produced sounds with intended targets.', NULL, '2025-12-14T23:32:07.083Z');
INSERT INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "options", "correct_answer", "explanation", "difficulty", "created_at") VALUES (85, 'course_17dbc904', 40, 'Easy-medium application: When practicing connected speech to improve fluency, why is it important to coordinate breathing exercises with articulatory practice?', '["Breath is unrelated; only articulation matters","Because breath timing and pressure must align with proprioceptive and auditory feedback to maintain fluent and stable speech over time","Because breathing exercises replace the need for proprioception","Because breathing solely fixes all syntactic errors"]', 'B', 'Breath regulation is coordinated with proprioceptive and auditory streams to sustain fluent output; aligning breathing with articulation supports stable speech.', NULL, '2025-12-14T23:32:07.083Z');
